      null,
      '${missionOnceId}'::uuid,
      null,
      null
    ) as r;
  `);
  assert.equal(updateRes.rows[0].r.report_id, reportOnceId, 'Must update the exact same report ID');
  console.log('PASS: Day 2 once-mode submission safely updated pending report on same record across days');
});

